230→// extractFirstPromptFromTranscript reads transcript bytes and returns the first user prompt.
231→func extractFirstPromptFromTranscript(data []byte) string {
232→	lines, err := transcript.ParseFromBytes(data)
233→	if err != nil {
234→		return ""
235→	}
236→	for _, line := range lines {
237→		if line.Type == "user" {
238→			prompt := extractTextFromMessage(line.Message)
239→			if prompt != "" {
240→				return prompt
241→			}
242→		}
243→	}
244→	return ""
245→}
246→
247→// extractTextFromMessage extracts the text content from a transcript message.
248→func extractTextFromMessage(msg json.RawMessage) string {
249→	// Try string content first (simple user messages)
250→	var simple struct {
251→		Content string `json:"content"`
252→	}
253→	if err := json.Unmarshal(msg, &simple); err == nil && simple.Content != "" {
254→		return simple.Content
255→	}
256→
257→	// Try array content (messages with tool results, text blocks, etc.)
258→	var array struct {
259→		Content []struct {
260→			Type string `json:"type"`
261→			Text string `json:"text"`
262→		} `json:"content"`
263→	}
264→	if err := json.Unmarshal(msg, &array); err == nil {
265→		for _, block := range array.Content {
266→			if block.Type == "text" && block.Text != "" {
267→				return block.Text
268→			}
269→		}
270→	}
271→
272→	return ""
273→}
