237→// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
238→func promptAmendCommit(ctx context.Context, w io.Writer, checkpointIDStr string) error {
239→	// Get HEAD commit info
240→	repo, err := openRepository(ctx)
241→	if err != nil {
242→		return fmt.Errorf("failed to open repository: %w", err)
243→	}
244→	headRef, err := repo.Head()
245→	if err != nil {
246→		return fmt.Errorf("failed to get HEAD: %w", err)
247→	}
248→	headCommit, err := repo.CommitObject(headRef.Hash())
249→	if err != nil {
250→		return fmt.Errorf("failed to get HEAD commit: %w", err)
251→	}
252→
253→	shortHash := headRef.Hash().String()[:7]
254→	subject := strings.SplitN(headCommit.Message, "\n", 2)[0]
255→
256→	// Check if the commit already has this checkpoint trailer
257→	if _, found := trailers.ParseCheckpoint(headCommit.Message); found {
258→		fmt.Fprintf(w, "\nLast commit already has an Entire-Checkpoint trailer.\n")
259→		return nil
260→	}
261→
262→	fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)
263→
264→	amend := true
265→	form := NewAccessibleForm(
266→		huh.NewGroup(
267→			huh.NewConfirm().
268→				Title("Amend to last commit in this branch?").
269→				Affirmative("Y").
270→				Negative("n").
271→				Value(&amend),
272→		),
273→	)
274→	if err := form.Run(); err != nil {
275→		return fmt.Errorf("prompt failed: %w", err)
276→	}
277→
278→	if !amend {
279→		fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
280→		return nil
281→	}
282→
283→	// Amend the commit with the checkpoint trailer
284→	newMessage := fmt.Sprintf("%s\n\n%s: %s\n", strings.TrimRight(headCommit.Message, "\n"), trailers.CheckpointTrailerKey, checkpointIDStr)
285→
286→	cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "-m", newMessage)
287→	if output, err := cmd.CombinedOutput(); err != nil {
288→		return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
289→	}
290→
291→	fmt.Fprintf(w, "Amended commit %s with Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
292→	return nil
293→}
