295→// extractFirstPromptFromTranscript reads transcript bytes and returns the first user prompt.
296→func extractFirstPromptFromTranscript(data []byte) string {
297→	lines, err := transcript.ParseFromBytes(data)
298→	if err != nil {
299→		return ""
300→	}
301→	for _, line := range lines {
302→		if line.Type == "user" {
303→			prompt := extractTextFromMessage(line.Message)
304→			if prompt != "" {
305→				return prompt
306→			}
307→		}
308→	}
309→	return ""
310→}
