312→// extractTextFromMessage extracts the text content from a transcript message.
313→func extractTextFromMessage(msg json.RawMessage) string {
314→	// Try string content first (simple user messages)
315→	var simple struct {
316→		Content string `json:"content"`
317→	}
318→	if err := json.Unmarshal(msg, &simple); err == nil && simple.Content != "" {
319→		return simple.Content
320→	}
321→
322→	// Try array content (messages with tool results, text blocks, etc.)
323→	var array struct {
324→		Content []struct {
325→			Type string `json:"type"`
326→			Text string `json:"text"`
327→		} `json:"content"`
328→	}
329→	if err := json.Unmarshal(msg, &array); err == nil {
330→		for _, block := range array.Content {
331→			if block.Type == "text" && block.Text != "" {
332→				return block.Text
333→			}
334→		}
335→	}
336→
337→	return ""
338→}
